-- 192_replace_decision_53_2018_licensing_and_share_ownership_controls_for_non_banking_financial_companies_consolidated_text_without_preamble_or_titles_with_inline_page_numbers_and_flattened_tables.sql
--
-- إعادة هيكلة قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم (53) لسنة 2018 (بتاريخ 2018/4/26) بشأن ضوابط منح الترخيص واستمراره وقواعد تملك أسهم الشركات العاملة
-- فى الأنشطة المالية غير المصرفية، بالنص الموحد "وفقاً لأخر تعديل بتاريخ 2024/6/26" (تعديل بقرار مجلس إدارة الهيئة رقم 140 لسنة 2024) كما نشرته الهيئة على موقعها.
--
-- ===== الحالة السابقة (مراجعة الـ153 وثيقة، النص الموحد) =====
-- مخزَّن بـ13 صفاً (article_no = 1..13، إجمالى 19519 حرفاً) بلا ديباجة ولا عناوين مواد ولا hierarchical_location، وكل صف نسخة من الطبقة النصية للـPDF مباشرة، وعيوبه:
--   * وصلات الحروف مقلوبة فى الطبقة النصية: "األنشطة" بدل "الأنشطة"، "األحكام" بدل "الأحكام"، "لألوراق" بدل "للأوراق"، "اإليداع" بدل "الإيداع"، "وال تسري" بدل "ولا تسري"،
--     "والئحته" بدل "ولائحته"، "الالئحة" بدل "اللائحة"، "الثلاث عشر" بدل "الثالث عشر"... فى مئات المواضع، فلا يجد البحث النصى الكلمات الصحيحة؛
--   * أرقام الصفحات ("2" و"3" ...) وهوامش أسفل الصفحات (علامات الهوامش 2 و3 و4 و5 و6 و7 و8 و9 و14) مختلطة بالمتن فى منتصف الجمل والتعريفات، وفى الصف 13 هامشا المادتين 12 و13 (8 و9) ثم الجدول بعده؛
--   * عناوين الأبواب ملصقة بأطراف المواد: "تأسيس وترخيص الشركات العاملة يف الأنشطة املالية غري املصرفية" ملحقة بنهاية المادة 2 (فى الأصل قبل المادة 3 مباشرة)
--     و"ضوابط نقل ملكية أسهم ..." مفتتحة المادة 5، ومعها "(املادة ...)" بحروف مشوهة؛
--   * جدول التعريفات فى المادة 2 مسطح بعمودين مقلوبى الترتيب (المصطلح فى آخر السطر) وقائمة "المؤسسات المالية" بأرقام ملتصقة بالنص (".1البنوك") وتعريف الشركة ذات غرض الاستحواذ
--     (SPAC) بعبارته الإنجليزية مفككة ("PURPOSE SPECIAL / ACQUISITION / »:COMPANY«SPAC")، وجدول (1) المرفق ملحق بآخر صف (13) مع هامشه المرقم 14؛
--   * سقوط ديباجة القرار كلها (اطلاعاته الثمانية عشر وموافقة المجلس)، وعنوان القرار وعبارة "النص الموحد وفقاً لأخر تعديل".
-- (هذه أبرز العيوب لا حصرها؛ أُعيدت كتابة المتن كله من الأصل ولم يُعتمد على المخزَّن أساساً.)
--
-- ===== المصدر والمنهجية =====
-- PDF الهيئة الموحد (10 صفحات، مُنتَج بـ Word بوصلات حروف مقلوبة فى طبقته النصية، وخط العناوين بلا طبقة نصية سليمة: "املادة" و"جملس" و"الرتخيص"). نُقل النص كاملاً من الصفحات
-- بصرياً (200 dpi، كل صفحة فى ثلاثة أشرطة) ثم قوبل بطريقتين: (1) الطبقة النصية بعد تصحيح الوصلات، بمفاتيح الحروف المرتبة لكل كلمة (فلا تؤثر فيها الوصلات المقلوبة) فلم تبق فروق غير
-- المعروف منها (عناوين المواد، حروف مطولة بالتمطيط "النسبببببببة" و"خمسبببببببة" و"تصببببببنيفها"، علامة الهامش الملتصقة بالتاريخ "12024"، سطر "قرر"، وفاصل التنوين)، (2) مخرجات OCR مستقلة
-- (tesseract ara). وكُبِّرت المواضع التى يلتبس فيها الإملاء (الثالث/الثلاث، ألا/الا، التى/التي، بجوز، تنوين الفتح...). ما كان فى الطبقة النصية بوصلة مقلوبة محتمل اللبس حُسم بالبصر لا بالنص.
-- أُبقى إملاء الأصل وأخطاؤه كما هى: "لأخر تعديل"، "وفقاً التشريعات" (المادة 3)، "الأولي" و"علي" و"اليها" و"لا غيا" و"التامين" و"سوق راس المال" و"بجوز" و"خمسة مليار" و"مالم رد إليه اعتباره"
-- و"ألا يقل نسبة تمثيل المرأة" و"فى للقوانين" وهامش 1 "20/12/30" (بلا 19 فى الأصل) و"وقرر 171"، وعلامات الترقيم الشرطى ("ما يلي: -" و"-بحسب الأحوال-").
-- حُذفت ترويسة الصفحات وتذييلها وسطر "رئيس الهيئة" وسطر "مجلس إدارة الهيئة العامة للرقابة المالية" وكلمة "قرر" (لا توقيع مطبوع فى الأصل). الأرقام لاتينية، وأُسقطت علامات التشكيل الصغيرة وأُبقى تنوين الفتح
-- مكتوباً على الحرف قبل الألف كباقى الهجرات. علامات الهوامش فى المتن "(n)"؛ وما كان منها على عناوين المواد نُقل إلى عنوان المادة (المادة 2 (2)، المادة 4 (5)، المادة 8 (6)، المادة 12 (8)،
-- المادة 13 (9))، وعلامة (1) إلى hierarchical_location للديباجة مع عنوان القرار وعبارة "النص الموحد". عنوانا البابين المطبوعان يتصدران المادتين اللتين طُبعا معهما: "تأسيس وترخيص الشركات العاملة
-- فى الأنشطة المالية غير المصرفية" (قبل المادة 3) و"ضوابط نقل ملكية أسهم الشركات العاملة فى الأنشطة المالية غير المصرفية" (بعد عنوان المادة 5)، فأُلحق كل منهما بعنوان مادته دون ادعاء نطاق له.
--
-- ===== تعديلات التمثيل (معلنة) =====
--   * جدول التعريفات (المادة 2): كل صف صار فقرة "المصطلح: التعريف"، وقوائم "المؤسسات المالية" (21 بنداً) بأرقام "N-"، وبنود المستثمر المؤهل "أ) ... د)" كل بند فى سطر. علامة الهامش (3) بعد المصطلح "الشركة ذات غرض الاستحواذ".
--   * العبارة الإنجليزية لذلك المصطلح كتبتها بترتيبها المنطقى "SPECIAL PURPOSE ACQUISITION COMPANY: «SPAC»" عن شظاياها المطبوعة بترتيب بصرى مقلوب، وهى تعبير عن ترتيب الكلمات لا إضافة نص.
--   * جدول (1): كل صف صار سطراً "النشاط: المتطلب" تحت عنوان مجموعته، وقوائم التصنيف الائتمانى الأربع (Standard & Poors وFitch وMoody’s وA.M Best) كل منها فى سطر.
--     رُقِّم المحتوى فى القسم 14 (عنوانه كما طبع "جدول (1) (10)": علامة الهامش المطبوعة على العنوان 10 بينما الهامش نفسه مطبوع برقم 14 ولا هوامش 10–13 فى هذا الإصدار الموحد؛ أُبقى الرقمان كما طُبعا).
--   * علامة الهامش 9 مطبوعة فى الأصل "999" على المادة 13؛ كُتبت "(9)".
--   * البنود المنقوطة (النسب الأربع فى المادة 8) كُتبت "- ..." فى سطر لكل بند.
--
-- ===== الهيكل =====
-- 16 صفاً، 16 نسخة (version_no = 1): ديباجة (article_no = 0) بثمانية عشر اطلاعاً وموافقة المجلس، والمواد 1–13، ثم القسم 14 "جدول (1)"، ثم القسم 15 "هوامش التعديلات اللاحقة" وبه الهوامش
-- 1–9 و14 (كما طبعت؛ لا هوامش بالأرقام 10–13). المفتاح (1..13، 0) محفوظ فلا تعيد بذرة القرار إدراج المواد القديمة (إدراج laws فيها ON CONFLICT DO NOTHING، وإدراج المواد مبنى على RETURNING فلا يعمل مع قانون موجود).
--
-- ===== التاريخ والنسخ (قرار تقديرى يُراجَع) =====
-- النص المتاح هو الموحد بعد تعديل 2024/6/26 فقط؛ لا نص أصلى لعام 2018 ولا نصوص المراحل الوسيطة للتعديلات السبعة عشر الواردة فى الهامش 1 (من القرار 93 لسنة 2018 إلى القرار 140 لسنة 2024)،
-- ولا تاريخ نشر بالوقائع المصرية فى المصدر. فجُعل effective_from = 2024-06-26 (تاريخ آخر تعديل المذكور فى المصدر) للنسخ الست عشرة، وسُجِّل amended_by = 140/2024 مع change_note على المادتين
-- 2 (تعريف الشركة ذات غرض الاستحواذ) و3 (الفقرة الثانية) وحدهما، وهما اللتان أضافهما قرار 140/2024 بحسب الهامشين 3 و4. أما التعديلات السابقة على بقية المواد فتفصّلها الهوامش فى القسم 15 دون
-- إنشاء نسخ لها. أثر ذلك: لا نسخة للقرار قبل 2024-06-26 فى الاستعلام بالتاريخ (فجوة معلنة بدل نص معدَّل منسوب لتواريخ سابقة)، كما فعلت الهجرات 138 و154 و155. لاحقاً: رفع نصوص 2018 الأصلية والقرارات المعدِّلة
-- لبناء النسخ التاريخية. لا تُمس بيانات laws.
--
-- ===== تنبيه قانونى للمراجعة (لا يعالجه هذا الملف) =====
-- قرار مجلس إدارة الهيئة رقم 177 لسنة 2024 (بتاريخ 2024/8/28، المعاد رفعه بالهجرة 148) ينص على "يلغى قرار مجلس إدارة الهيئة رقم 53 لسنة 2018 المشار إليه"، أى أن هذا القرار ألغى بعد شهرين
-- من آخر تعديل له، وأن النص الموحد هنا هو آخر نص قبل الإلغاء. ما زالت laws.status لهذا القرار = in_force؛ ينبغى أن تُراجَع (repealed وتاريخ 2024-08-30 يوم العمل بقرار 177/2024) فى هجرة بيانات laws المؤجلة،
-- وهو ما يؤثر على ما يُجاب به عن "الأحكام السارية" لا على صحة هذا النص. وبقرار 177/2024 تحوّل هذا القرار إلى نص تاريخى؛ المواد باقية للاستشهاد بها فى الوقائع السابقة على الإلغاء.
--
-- ===== قابلية إعادة التشغيل =====
-- الحذف مشروط بألا تكون الحالة نظيفة (16 صفاً بديباجة سليمة والقسم 15 موجود)؛ والإدراج ON CONFLICT DO NOTHING. تحقق الختام محصور فى هذا القرار ويفشل عند أى انحراف
-- (عدد، لفظ مغاير للأصل، بقايا وصلات مقلوبة أو ترويسة أو علامات هوامش مختلطة، محتوى المواد، تاريخ سريان الأفرع، إجمالى الطول 21671 حرفاً).
--
-- ملاحظة تشغيلية: المواد الجديدة بلا embedding؛ يلزم scripts/backfill-embeddings.js بعد النشر.
BEGIN;
DO $fix192$
DECLARE
  v_law_id uuid;
  v_n int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 53 AND law_year = 2018 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[192] القرار 53/2018 غير موجود فى laws — تخطّى';
    RETURN;
  END IF;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law_id) = 16
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND title = 'ديباجة القرار' AND body LIKE 'بعد الاطلاع%')
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 15 AND article_suffix_order = 0) THEN
    RAISE NOTICE '[192] القرار 53/2018 نظيف بالفعل — تخطّى الحذف';
  ELSE
    SELECT count(*) INTO v_n FROM articles WHERE law_id = v_law_id;
    DELETE FROM articles WHERE law_id = v_law_id;
    RAISE NOTICE '[192] أُزيلت % مادة من القرار 53/2018 (القرار بنص موحد مخزَّن بلا ديباجة ولا عناوين مواد وبطبقة نصية بوصلات حروف مقلوبة وأرقام صفحات وهوامش مختلطة بالمتن وجدول مسطح)', v_n;
  END IF;
END
$fix192$;

WITH ins0_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 0, 0, $h0$قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم (53) لسنة 2018 بتاريخ 2018/4/26 بشأن ضوابط منح الترخيص واستمراره وقواعد تملك أسهم الشركات العاملة في الأنشطة المالية غير المصرفية (النص الموحد وفقاً لآخر تعديل بتاريخ 2024/6/26) (1)$h0$, $t0_0$ديباجة القرار$t0_0$, $b0_0$بعد الاطلاع على القانون رقم (10) لسنة 1981 بشأن الإشراف والرقابة على التأمين في مصر ولائحته التنفيذية؛
وعلى قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد الصادر بالقانون رقم (159) لسنة 1981 ولائحته التنفيذية؛
وعلى قانون سوق رأس المال الصادر بالقانون رقم (95) لسنة 1992 وتعديلاته ولائحته التنفيذية والقرارات الصادرة تنفيذًا لهما؛
وعلى قانون التأجير التمويلي الصادر بالقانون رقم (95) لسنة 1995 ولائحته التنفيذية؛
وعلى القانون رقم (93) لسنة 2000 بإصدار قانون الإيداع والقيد المركزي للأوراق المالية ولائحته التنفيذية؛
وعلى قانون التمويل العقاري الصادر بالقانون رقم (148) لسنة 2001 ولائحته التنفيذية؛
وعلى قانون مكافحة غسل الأموال الصادر بالقانون رقم (80) لسنة 2002 ولائحته التنفيذية؛
وعلى القانون رقم (10) لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية؛
وعلى القانون رقم (141) لسنة 2014 بتنظيم نشاط التمويل متناهي الصغر؛
