SELECT id, 1, body, '2024-06-26', 'active' FROM ins1_0;

WITH ins2_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 0, NULL, $t2_0$المادة الثانية (2)$t2_0$, $b2_0$في تطبيق أحكام هذا القرار، يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها:
الشركة العاملة في الأنشطة المالية غير المصرفية: هي الشركة المرخص لها من الهيئة بمزاولة أي من الأنشطة المالية غير المصرفية، ويشار إليها في أحكام هذا القرار ب «الشركة العاملة».
المساهم الرئيسي: المساهم المالك لنسبة 10% فأكثر من رأس مال الشركة سواء بمفرده أو من خلال أطرافه المرتبطة.
الأطراف المرتبطة: يقصد بالأطراف المرتبطة الأشخاص الذين يجمع بينهم اتفاق بغرض الاستحواذ أو السيطرة الفعلية على إحدى الشركات الخاضعة لأحكام هذا القرار، ويعد من بينهم الأشخاص الطبيعية وأقاربهم حتى الدرجة الثانية أو الأشخاص الاعتبارية إذا كانت تحت السيطرة الفعلية لذات الأشخاص الطبيعية أو الاعتبارية، وكذلك مجموع الأشخاص الخاضعة للسيطرة الفعلية لذات الأشخاص الطبيعية أو الاعتبارية أو الذي يكون بينهم اتفاق على ممارسة حقوقهم في الجمعية العامة أو مجلس إدارة الشركة بما يؤدي إلى السيطرة الفعلية على أي منهما.
المؤسسات المالية:
1- البنوك المصرية وفروع البنوك الأجنبية الخاضعة لإشراف البنك المركزي المصري.
2- شركات التأمين أو إعادة التأمين.
3- الشركات التي يكون غرضها الاشتراك في تأسيس الشركات التي تصدر أوراق مالية أو زيادة رؤوس أموالها.
4- الشركات والجهات التي تزاول نشاط البورصات.
5- شركات الوساطة في السندات والمتعاملون الرئيسيون.
6- شركات رأس المال المخاطر.
7- شركات المقاصة والإيداع والقيد المركزي.
8- شركات التمويل العقاري أو إعادة التمويل العقاري.
9- شركات التأجير التمويلي أو التخصيم.
10- شركات التمويل الاستهلاكي.
11- شركات تمويل المشروعات المتوسطة والصغيرة و/أو متناهية الصغر.
12- صناديق الاستثمار.
13- شركات الاستثمار المباشر.
14- الهيئة القومية للبريد.
15- صناديق التأمين الخاصة التي تبلغ حجم أموالها المستثمرة أكثر من 100 مليون جنيه.
16- جهاز تنمية المشروعات المتوسطة والصغيرة ومتناهية الصغر.
17- صندوق مصر السيادي للاستثمار والتنمية.
18- صندوق مصر الفرعي للخدمات المالية والتحول الرقمي.
19- الشركات أو الجهات من الأشخاص الاعتبارية العامة والخاصة الصادر بشأنها قرار من مجلس إدارة الهيئة.
20- الأشخاص الاعتبارية الأجنبية التي تمارس إحدى الأنشطة المالية المصرفية أو غير المصرفية الخاضعة لإشراف ورقابة جهة تمارس اختصاصات مثيلة للبنك المركزي المصري أو الهيئة بحسب الأحوال.
21- المؤسسات المالية العربية والإقليمية والدولية التي توافق عليها الهيئة.
التملك المباشر: الحالات التي يتم فيها تملك أسهم أو السندات القابلة للتحويل إلي أسهم بالشركات العاملة وذلك باسم طالب التملك أو أطرافه المرتبطة، ويدخل في حساب الملكية شهادات الإيداع الأجنبية المقابلة لأسهم الشركات.
التملك غير المباشر: هي نسبة المساهمة لأحد الأشخاص من خلال أطرافه المرتبطة في رأس مال الشركة المرخص لها المستهدفة أفقيًا أو رأسيًا وصولًا للمستفيد النهائي.
المستثمر المؤهل: يقصد بالمستثمر المؤهل أي مما يلي:
أ) الأشخاص الطبيعيون من ذوي الخبرة التي لا تقل عن عشر سنوات في مجال إدارة الأموال واستثمارها و/ أو الاستثمار المباشر و/أو المجالات المرتبطة بالأنشطة المالية المصرفية أو غير المصرفية، على ألا تقل قيمة الأصول السائلة أو الأوراق أو الأدوات المالية المملوكة له عن عشرة ملايين جنيه.
ب) الجهات الحكومية والأشخاص الاعتبارية العامة وأجهزة الدولة التي تسمح القوانين والقرارات المنظمة لها بمزاولة أنشطة مالية واستثمارية بما فيها تأسيس الشركات أو المساهمة فيها.
ج) شركات الأموال التي لا يقل حقوق ملكيتها عن عشرة ملايين جنيه.
د) المؤسسات المالية المشار إليها بهذا القرار.
الشركة ذات غرض الاستحواذ (3) (SPECIAL PURPOSE ACQUISITION COMPANY: «SPAC»): هي إحدى الشركات التي يتم تأسيسها والترخيص لها كشركة رأس مال مخاطر، وتكون ذات غرض وحيد هو الاستحواذ على شركات أخرى، وتقوم بالحصول على التمويل اللازم للقيام بعمليات الاستحواذ من خلال طرح زيادة رأس مالها في اكتتاب خاص.$b2_0$
  FROM laws WHERE law_no = 53 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
