SELECT id, 1, body, '2024-06-26', 'active', 140, 2024, $c2_0$النص الموحد: إضافة تعريف «الشركة ذات غرض الاستحواذ» (SPAC) إلى المادة الثانية بقرار مجلس إدارة الهيئة رقم (140) بتاريخ 2024/6/26$c2_0$ FROM ins2_0;

WITH ins3_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 3, 0, NULL, $t3_0$المادة الثالثة - تأسيس وترخيص الشركات العاملة في الأنشطة المالية غير المصرفية$t3_0$, $b3_0$تكون الموافقة على طلبات تأسيس أو ترخيص الشركات العاملة في ضوء حاجة السوق للنشاط المطلوب الترخيص به أو تأسيس شركة لمباشرته بناءً على دراسة للسوق تعتمد من مجلس إدارة الهيئة أو تقديم منتجات جديدة أو تطوير منتجات قائمة -بحسب الأحوال-، وبمراعاة توافر الاشتراطات الأخرى الواجب الالتزام بها وفقًا التشريعات المنظمة لكل نشاط.
وبالنسبة للشركات ذات غرض الاستحواذ فتلتزم بتقديم طلب قيد أسهمها بالبورصة خلال شهر من تاريخ حصولها على الترخيص وإلا اعتبر ترخيصها كأن لم يكن، وفى حال شطب قيد أسهم الشركة من البورصة يتم إلغاء ترخيصها وتلتزم باتخاذ إجراءات التصفية، وذلك ما لم تقدم الشركة مبررات تقبلها الهيئة. (4)$b3_0$
  FROM laws WHERE law_no = 53 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, amended_by_law_no, amended_by_law_year, change_note)
SELECT id, 1, body, '2024-06-26', 'active', 140, 2024, $c3_0$النص الموحد: إضافة الفقرة الثانية من المادة الثالثة (الشركات ذات غرض الاستحواذ) بقرار مجلس إدارة الهيئة رقم (140) بتاريخ 2024/6/26$c3_0$ FROM ins3_0;

WITH ins4_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 4, 0, NULL, $t4_0$المادة الرابعة (5)$t4_0$, $b4_0$مع عدم الإخلال بمتطلبات التأسيس أو الترخيص المطلوبة وفقا للتشريعات المنظمة لكل نشاط، يجب على الشركات الراغبة في الحصول على موافقة مبدئية على التأسيس أو الحصول على ترخيص بمزاولة أحد الأنشطة المالية غير المصرفية، الالتزام بما يلي:
1- تقديم دراسة الجدوى الفنية والاقتصادية للشركة وفقًا للنموذج المعتمد من الهيئة.
2- ألا تقل نسبة مساهمة المؤسسة المالية عن (25%) من رأس مال الشركة، أو ألا تقل نسبة مساهمة المستثمر المؤهل عن ثلثي رأس مال الشركة، مع الالتزام بالضوابط الخاصة بهيكل الملكية لبعض الأنشطة المالية غير المصرفية على النحو الوارد بالجدول رقم (1) المرفق بهذا القرار.
3- الإفصاح عن المستفيد النهائي للمساهمين وفقًا للأحكام الواردة بالباب الثالث عشر من اللائحة التنفيذية لقانون سوق رأس المال.
4- وجوب استخدام أسلوب التصويت التراكمي في انتخاب أعضاء مجلس الإدارة بما يسمح بالتمثيل النسبي في عضوية مجلس الإدارة كلما أمكن ذلك.
5- ألا يقل نسبة تمثيل المرأة في مجلس إدارة الشركة عن (25%).
6- الانتهاء من إجراءات التأسيس خلال فترة لا تزيد علي ستة أشهر من تاريخ موافقة الهيئة المبدئية، ويجوز للهيئة مدها لمدد أخرى بناءً على مبررات تقبلها الهيئة وبمراعاة التشريعات المنظمة لبعض الأنشطة، وفى حالة عدم إنهاء تأسيس الشركة في المدد المحددة تعتبر موافقة الهيئة المبدئية كأن لم تكن.
7- استيفاء كافة متطلبات الحصول على الترخيص خلال ثلاثة أشهر على الأكثر من تاريخ القيد بالسجل التجاري، ويجوز مدها بناءً على مبررات تقبلها الهيئة، وفى حالة تجاوز الشركة المدد المحددة للتقدم بمستندات الترخيص يجوز للهيئة في ضوء حاجة السوق قبول الطلب بعد تحديث مستندات الشركة بما فيها تقديم دراسة جدوى فنية واقتصادية جديدة واستيفاء كافة متطلبات الترخيص بمزاولة النشاط وفقًا للضوابط المعمول بها وقت تقديم طلب الترخيص، على أن يكون من بينها توافر خبرة في القطاع المالي المصرفي و/أو غير المصرفي لدى نصف أعضاء مجلس إدارة الشركة على الأقل بخلاف العضو المنتدب وذلك وفقًا لمدد الخبرة المنصوص عليها بقرارات مجلس إدارة الهيئة الصادرة في شأن كل نشاط، ومع الالتزام بأن يكون ربع أعضاء مجلس إدارة شركات التأمين على الأقل من ذوي الخبرة في مجال التأمين. ولا تسري متطلبات الخبرة الواردة بهذا البند في شأن الشركات التي تقدم استشارات مهنية.
8- أن يتم بدء العمل في النشاط والانتهاء من التجهيزات المطلوبة وتعيين فريق العمل بالخبرات المطلوبة وفقًا لكل نشاط والبدء الفعلي للنشاط خلال ستة أشهر على الأكثر من تاريخ الحصول على الترخيص، ويجوز مد هذه المدة في ضوء المبررات التي تقدمها الشركة وتقبلها الهيئة، وفي حالة عدم البدء الفعلي للنشاط في المدد المحددة يعتبر الترخيص لا غيا.
9- استيفاء نموذج الإفصاح المعد من الهيئة في شأن التحقق من مصادر أموال مؤسسي الشركة ومساهميها الرئيسيين.
10- ألا يكون أي من مؤسسي الشركة أو مساهميها الرئيسيين أو المستفيدين النهائيين أو أعضاء مجلس الإدارة مدرجين في القوائم السلبية المتعلقة بالعقوبات المحلية أو الدولية.
ويشترط أن يتوافر في الشخص الاعتباري الذي يجوز له المشاركة في تأسيس الشركات العاملة ما يلي:
أ- ألا يكون في حالة إعسار مالي أو إفلاس.
ب- ألا تكون الهيئة قد اتخذت ضده أو أي من مساهميه الرئيسين أو أعضاء مجلس إدارته إجراءات تحريك الدعوي الجنائية بشأن أحد الجرائم المنصوص عليها في القوانين والقواعد المنظمة للأنشطة المالية غير المصرفية أو صدرت ضد أي منهم أحكام قضائية نهائية في أي من تلك الجرائم والجرائم المنصوص عليها بقانون البنك المركزي والجهاز المصرفي أو قانون مكافحة غسل الأموال خلال الثلاث سنوات السابقة على طلب التأسيس ما لم يكن قد تصالح عنها، أو يكون قد صدر ضد أي منهم أحكام نهائية بعقوبة جنائية أو جنحة في جريمة مخلة بالشرف أو الأمانة مالم رد إليه اعتباره.
ج- ألا تكون الجهة الإدارية التابع لها قد اتخذت ضده أي من التدابير الاحترازية أو الجزاءات الإدارية-باستثناء التنبيه والإنذار- خلال السنوات الثلاث السابقة على طلب التأسيس مالم تكن قد ازيلت أسبابها ومرت ستة أشهر على تلك الإزالة.
كما تسري الأحكام الواردة بالبنود السابقة على المستثمرين المؤهلين المشاركين في تأسيس الشركة العاملة.
وتلتزم الشركات الحاصلة على ترخيص بمزاولة أحد الأنشطة المالية غير المصرفية بإخطار الهيئة قبل قيامها بإجراء أي تعديل في تشكيل مجالس إدارتها، ويعد مضي أسبوعين دون رد من الهيئة بمثابة موافقة على إجراء هذا التعديل.$b4_0$
  FROM laws WHERE law_no = 53 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-06-26', 'active' FROM ins4_0;

WITH ins5_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 5, 0, NULL, $t5_0$المادة الخامسة - ضوابط نقل ملكية أسهم الشركات العاملة في الأنشطة المالية غير المصرفية$t5_0$, $b5_0$مع عدم الإخلال بالمادة (27 مكررًا 1) من قانون الإشراف والرقابة على التأمين في مصر، وكذا أحكام الباب الثاني عشر من اللائحة التنفيذية لقانون سوق رأس المال والمادتين 328 مكررًا، 328 مكررًا 1 منه، تسري الأحكام التالية بشأن ضوابط تملك الشخص الطبيعي أو الاعتباري -بطريق مباشر أو غير مباشر سواء بمفرده أو من خلال مجموعة مرتبطة - في رأسمال أو حقوق التصويت بأي شركة من الشركات العاملة.$b5_0$
  FROM laws WHERE law_no = 53 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-06-26', 'active' FROM ins5_0;

WITH ins6_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 6, 0, NULL, $t6_0$المادة السادسة$t6_0$, $b6_0$على كل شخص طبيعي أو اعتباري يمتلك 5% من رأس مال أو حقوق التصويت لإحدى الشركات العاملة أن يخطر الهيئة بذلك خلال أسبوعين من تاريخ تملكه لهذه النسبة.
ويحظر على أي شخص طبيعي – بغير طريق الميراث أو الوصية -أو على أي شخص اعتباري أن يمتلك نسبة 10% من رأس المال المصدر للشركة العاملة أو حقوق التصويت بها زيادة ملكيته فيها بنسبة 5% ومضاعفاتها إلا بعد الحصول على موافقة مسبقة من الهيئة، وذلك مع عدم الإخلال بنسب الملكية القائمة وقت العمل بهذا القرار بشرط عدم زيادة هذه النسب إلا بموافقة مسبقة من الهيئة.
لا يجوز نقل ملكية أسهم الشركات العاملة في الفترة من تاريخ التأسيس وحتى الترخيص إلا بموافقة مسبقة من الهيئة وأن يتوافر في المساهم الجديد ذات المتطلبات الواردة بالمادة الرابعة من هذا القرار.$b6_0$
  FROM laws WHERE law_no = 53 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-06-26', 'active' FROM ins6_0;

WITH ins7_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 7, 0, NULL, $t7_0$المادة السابعة$t7_0$, $b7_0$تقدم طلبات نقل ملكية أسهم الشركات العاملة إلى الهيئة، ويرفق بالطلب ما يلي: -
1- بيان يتضمن كمية ونسبة الأوراق المالية أو حقوق التصويت محل التعامل.
2- بيان بالمساهمات المباشرة وغير المباشرة في رأس مال أو حقوق التصويت بأي من الشركات العاملة الأخرى في ذات النشاط متضمنا اسم الشركة ونسبة وكمية المساهمة وذلك بالنسبة لمقدم الطلب وأطرافه المرتبطة.
3- أي اتفاق أو تنسيق ما بين أشخاص طبيعيين أو اعتباريين تتعلق بكيفية ممارسة حقوقهم في الجمعية العامة أو مجلس إدارة الشركة محل طلب التملك.
4- الإفصاح عن المستفيد النهائي لطالب التملك وفقًا للقواعد والأحكام الواردة بالباب الثالث عشر من اللائحة التنفيذية لقانون سوق راس المال.
5- إقرار من طالب التملك أو ممثله القانوني بصحة كافة المستندات والبيانات المقدمة للهيئة.
6- بيان بالمؤهلات العلمية وبالخبرات العملية في مجال عمل الشركة بالنسبة للأشخاص الطبيعيين.
7- بيان معتمد من طالب التملك بالأحكام الصادرة ضده خلال الثلاث سنوات السابقة على تقديم الطلب في إحدى الجرائم أو المخالفات المنصوص عليها في الأنشطة المالية غير المصرفية أو قانون الشركات أو قانون البنك المركزي والجهاز المصرفي والنقد أو قانون مكافحة غسل الأموال وتمويل الإرهاب أو قانون حماية المنافسة ومنع الممارسات الاحتكارية أو بجريمة ماسة بالشرف والأمانة، أو تقديم إقرار بعدم صدور أية أحكام بشأن تلك الجرائم أو المخالفات.
8- ما يفيد سداد مقابل خدمات فحص ودراسة طلب التملك.
وفى حالة طلبات التملك لنسبة 25% أو أكثر من رأس المال أو حقوق التصويت، يتم تقديم المستندات والبيانات الإضافية التالية: -
1- الأهداف التي يرمى مقدم الطلب إلى تحقيقها من التملك.
2- الخطة الاستثمارية المستقبلية وتوجهاته فيما يتعلق بإدارة الشركة والسياسة التي ينوى إتباعها في تصريف شئونها.
3- صحيفة الحالة الجنائية وشهادة بمدى صدور أحكام حجر أو إفلاس للأشخاص الطبيعيين (أو ما يقابلها بالنسبة للأجانب).
4- إذا كان الطالب بنكا أو مؤسسة مالية أجنبية يتعين تقديم ما يثبت خضوعه لرقابة سلطة رقابية في الدولة التي يقع بها مقره الرئيسي تشابه اختصاصات البنك المركزي المصري أو اختصاصات الهيئة في مجال النشاط، مع ارفاق شهادة بالجزاءات أو التدابير الموقعة من الجهة الرقابية الخاضع لها الشخص الاعتباري طالب التملك حال كونه بنك أجنبي أو مؤسسة مالية أجنبية.
5- تعهد من الشخص الاعتباري وممثله القانوني بإخطار الهيئة مسبقًا في حال تغير السيطرة والالتزام بإرسال هيكل الملكية الجديد للشخص الاعتباري متضمنًا كل من يملك 10% أو أكثر من أسهمه أو حقوق التصويت به، وضرورة الحصول على موافقة الهيئة المسبقة في حال ترتب على تغيير السيطرة على الشخص الاعتباري تجاوز النسب المحددة بهذا القرار.$b7_0$
  FROM laws WHERE law_no = 53 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-06-26', 'active' FROM ins7_0;

WITH ins8_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 8, 0, NULL, $t8_0$المادة الثامنة (6)$t8_0$, $b8_0$يراعى عند البت في طلبات الحصول على موافقة الهيئة على التملك الاعتبارات التالية: -
1- مدى توافر عناصر الأهلية والكفاءة والخبرة العملية في مجال عمل الشركة في ضوء نسبة الملكية المطلوبة بالنسبة للأشخاص الطبيعيين.
2- مدى مساهمة طالب التملك والأطراف المرتبطة به في الشركة المطلوب الاستحواذ عليها وغيرها من الشركات العاملة في ذات النشاط وتأثير ذلك على السيطرة في ضوء نسبة الملكية المطلوبة.
3- مدى صدور أحكام قضائية نهائية ضد مقدم الطلب بإشهار الإفلاس، أو إدانته بجريمة ماسة بالشرف أو الأمانة، أو بإحدى الجرائم المقيدة للحرية المنصوص عليها في للقوانين التي تشرف عليها الهيئة أو قانون البنك المركزي والجهاز المصرفي والنقد أو في قانون مكافحة غسل الأموال وتمويل الإرهاب أو قانون حماية المنافسة ومنع الممارسات الاحتكارية.
4- مدى وجود تحقيقات تجريها الهيئة أو طلبات لتحريك الدعوى الجنائية بشأن مخالفات جسيمة للقوانين التي تشرف عليها الهيئة سواء كانت ضد الشخص الطبيعي طالب التملك أو ضد رئيس مجلس الإدارة أو العضو المنتدب للشركة طالبة التملك.
5- الالتزام بإعمال نظام التصويت التراكمي في انتخاب أعضاء مجلس إدارة الشركة بما يسمح بالتمثيل النسبي في عضوية مجلس الإدارة كلما أمكن ذلك.
وفي جميع الأحوال؛ يجب الحصول على موافقة مجلس إدارة الهيئة في حالة طلبات التملك للشخص ومجموعته المرتبطة لشركة تمثل 10% فأكثر من حجم السوق لأي نشاط، وذلك في حالة نسب الاستحواذ التالية: -
- ثلث رأس المال أو حقوق التصويت.
- نصف رأس المال أو حقوق التصويت.
- ثلثي رأس المال أو حقوق التصويت.
- ثلاثة أرباع رأس المال أو حقوق التصويت.
ويتم حساب حجم السوق لكل نشاط وفقًا لأخر بيانات سنوية سابقة على تقديم طلب التملك.
6- الالتزام بالبندين (9، 10) المنصوص عليهما في المادة الرابعة من هذا القرار في شأن طالب التملك (المساهم الرئيسي) والمستفيد النهائي.
وفي جميع الأحوال، يجب الحصول على موافقة مسبقة من الهيئة أو مجلس إدارة الهيئة بحسب الأحوال قبل إجراء الفحص النافي للجهالة لأي من الشركات العاملة في الأنشطة المالية غير المصرفية وذلك وفقًا للنموذج التي تضعه الهيئة في هذا الشأن. (7)$b8_0$
  FROM laws WHERE law_no = 53 AND law_year = 2018 AND kind = 'board_decision'
