WITH ins14_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 14, 0, NULL, $t14_0$جدول (1) (10)$t14_0$, $b14_0$النشاط - نسبة مساهمة المؤسسة المالية او المستثمرون المؤهلون
الشركات العاملة في مجال الأوراق المالية
1- تقييم وتصنيف وترتيب الأوراق المالية: لا يشترط توافر مؤسسة مالية أو مستثمر مؤهل.
2- الاستشارات المالية عن الأوراق المالية: لا يشترط توافر مؤسسة مالية أو مستثمر مؤهل.
الشركات العاملة في مجال التأمين
1- شركات التأمين (أشخاص/ممتلكات): يشترط أن تكون نسبة المساهمة المملوكة للشركات التامين وإعادة التامين بها لا تقل عن 25% من رأس المال، على أن تكون شركة التأمين مصنفة من قبل أحد جهات التصنيف الدولية التالية وبما لا يقل عن التصنيف قرين كل جهة:
Standard & Poors (BBB)
Fitch (BBB)
Moody’s (Baa)
A.M Best (B+)
وفي حالة انخفاض هذه النسبة بعد الترخيص بسبب زيادات رؤوس الأموال، بجوز استكمال هذه النسبة من المؤسسات المالية شريطة ألا تقل حقوق ملكيتها عن خمسة مليار جنيه ولا يقل تصنيفها الائتماني عن المستوى الدال على القدرة بالوفاء بالالتزامات (BBB+).
2- شركات الوساطة في التأمين / إعادة التأمين: يشترط توافر مؤسسات مالية بنسبة لا تقل عن (25%).
3- شركات خبراء المعاينة وتقدير الأضرار: لا يشترط توافر مؤسسة مالية أو مستثمر مؤهل.
4- شركات خبراء التأمين الاستشاريين: لا يشترط توافر مؤسسة مالية أو مستثمر مؤهل.
الشركات العاملة في مجال التمويل العقاري
1- شركات إعادة التمويل العقاري: الالتزام بحكم البند (ب) من المادة (30) من اللائحة التنفيذية لقانون التمويل العقاري.
2- شركات خبرة التقييم العقاري: لا يشترط توافر مؤسسة مالية أو مستثمر مؤهل.
3- شركات وساطة التمويل العقاري: لا يشترط توافر مؤسسة مالية أو مستثمر مؤهل.
الشركات العاملة في مجال التمويل الاستهلاكي
شركات التمويل الاستهلاكي: الالتزام بحكم البند (3) من المادة (9) من قانون تنظيم نشاط التمويل الاستهلاكي.$b14_0$
  FROM laws WHERE law_no = 53 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-06-26', 'active' FROM ins14_0;

WITH ins15_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 15, 0, $h15$قرار مجلس إدارة الهيئة رقم (53) لسنة 2018 - هوامش التعديلات اللاحقة$h15$, $t15_0$هوامش التعديلات اللاحقة$t15_0$, $b15_0$(1) تم تعديل القرار بموجب قرار مجلس إدارة الهيئة رقم 93 بتاريخ 2018/6/10 وقرار رقم 143 بتاريخ 2018/9/13 وقرار رقم 155 بتاريخ 2018/9/30 وقرار رقم 74 بتاريخ 2019/6/20 وقرار رقم 124 بتاريخ 2019/9/16 وقرار رقم 179 بتاريخ 20/12/30 وقرار رقم 65 بتاريخ 2020/4/8 وقرار رقم 175 بتاريخ 2020/11/18 وقرار رقم 96 بتاريخ 2021/6/6 وقرار رقم 110 بتاريخ 2021/7/5، وقرار رقم 166 بتاريخ 2021/10/31 وقرر 171 بتاريخ 2021/11/17 وقرار رقم 206 بتاريخ 2021/12/21 وقرار رقم 9 بتاريخ 2022/1/23 وقرار رقم 25 بتاريخ 2022/2/20 وقرار رقم 249 بتاريخ 2023/11/29، وقرار رقم 140 بتاريخ 2024/6/26.
(2) تم إضافة البندين 14،15 بتعريف المؤسسات المالية بموجب قرار مجلس إدارة الهيئة رقم 143 بتاريخ 2018/9/13، ثم تم استبدال (تعريف مصطلحات «الشركة العاملة في الأنشطة المالية غير المصرفية "الشركة العاملة"»، «المؤسسات المالية»، «التملك غير المباشر» والواردة بالمادة الثانية.)، وإضافة تعريف جديد لمصطلح «المستثمر المؤهل» بموجب قرار مجلس إدارة الهيئة رقم 249 بتاريخ 2023/11/29.
(3) تم إضافة تعريف جديد (الشركة ذات غرض الاستحواذ) بموجب قرار مجلس إدارة الهيئة رقم (140) بتاريخ 2024/6/26.
(4) تم إضافة الفقرة الثانية ب (المادة الثالثة) بموجب قرار مجلس إدارة الهيئة رقم 140 بتاريخ 2024/6/26.
(5) تم استبدال نص المادة الرابعة بموجب قرار مجلس إدارة الهيئة رقم 249 بتاريخ 2023/11/29.
(6) أضيف البند رقم 5 من المادة الثامنة بموجب قرار مجلس إدارة الهيئة رقم 93 بتاريخ 2018/6/10 ثم تم تعديله بموجب قرار المجلس رقم 155 بتاريخ 2018/9/30 وأضيف البند رقم 6 بموجب قرار مجلس إدارة الهيئة رقم 206 بتاريخ 2021/12/21.
(7) تم إضافة الفقرة الأخيرة من المادة الثامنة بموجب قرار مجلس إدارة الهيئة رقم 25 بتاريخ 2022/2/20.
(8) تم حذف عبارة (عدا البند رقم 2 من المادة الثالثة منه) الواردة بالبند رقم 2 من المادة الثانية عشرة بموجب قرار المجلس رقم 65 بتاريخ 2020/4/8.
(9) لا تسري أحكام قرار مجلس إدارة الهيئة رقم 249 بتاريخ 2023/11/29 على الشركات السابق حصولها على ترخيص بمزاولة أي من الأنشطة المالية غير المصرفية وتزاول النشاط فعليًا.
وعلى الشركات المرخص لها بمزاولة أحد الأنشطة المالية غير المصرفية ولم تقم بمزاولة النشاط فعليًا أن توفق أوضاعها باستيفاء المتطلبات اللازمة لمزاولة النشاط وفقًا لأحكام قرار مجلس إدارة الهيئة رقم (53) لسنة 2018 المشار إليه، خلال مدة لا تجاوز ستة أشهر من تاريخ العمل بهذا القرار، وفى حال عدم التزام الشركات بتوفيق أوضاعها أو تقديم مبررات تقبلها الهيئة لمد مهلة مزاولة النشاط يعرض الأمر على مجلس إدارة الهيئة للنظر في إلغاء الترخيص الممنوح لها.
كما يلغى قرار مجلس إدارة الهيئة رقم 74 لسنة 2019.
(14) تم تعديل البند رقم 1 الخاص بتقييم وتصنيف وترتيب الأوراق المالية من الجدول (1) بموجب قرار مجلس إدارة الهيئة رقم 74 بتاريخ 2019/6/20 ثم تم التعديل بموجب قرار المجلس رقم 9 بتاريخ 2022/1/23، ثم تم استبدال الجدول بموجب قرار مجلس إدارة الهيئة رقم 249 بتاريخ 2023/11/29، على أن تلتزم شركات تقييم وتصنيف وترتيب الأوراق المالية بإصدار وثيقة تأمين ضد الأخطار المهنية وفقًا للشروط التي تضعها الهيئة بما يتلاءم مع حجم ونطاق المسئوليات المترتبة على مزاولة مهامها، كما يجب استيفاء العضو المنتدب لهذه الشركات والعاملين بها من شاغلي الوظائف الرئيسية الخبرة الكافية في مجال تصنيف الأوراق المالية أو في مجال تحليل الائتمان ودراسة الجدارة الائتمانية وفقًا للمادة (285) من اللائحة التنفيذية لقانون سوق رأس المال، واجتياز العضو المنتدب لتلك الشركات المقابلة الشخصية بالهيئة والاختبارات اللازمة لشغل هذا المنصب.
ويجب على الشركات المشار إليها مزاولة نشاطها وفقًا لنموذج العمل المتبع لدى إحدى الجهات الدولية الواردة بقرار مجلس إدارة الهيئة رقم (71) لسنة 2009، أو أن تقدم شهادة من إحدى هذه الجهات تفيد العمل وفقًا للنموذج المتبع لديها.$b15_0$
  FROM laws WHERE law_no = 53 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-06-26', 'active' FROM ins15_0;

DO $verify192$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 53 AND law_year = 2018 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[192] القرار 53/2018 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 16 THEN RAISE EXCEPTION '[192] عدد المواد % بدل 16', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2024-06-26';
  IF v_v <> 16 THEN RAISE EXCEPTION '[192] عدد النسخ % بدل 16', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%األنشطة%' OR body LIKE '%األحكام%' OR body LIKE '%لألوراق%' OR body LIKE '%اإليداع%' OR body LIKE '%األشخاص%' OR body LIKE '%الالئحة%' OR body LIKE '%والئحته%' OR body LIKE '%وال تسري%' OR body LIKE '%جملس%' OR body LIKE '%املالية%' OR body LIKE '%املادة%' OR body LIKE '%12024%' OR body LIKE '%999%' OR body LIKE '%القرار ،%' OR body LIKE '%نبنى الجسور%' OR body LIKE '%FINANCIAL REGULATORY%' OR body LIKE '%WWW.FRA%' OR body LIKE '%رئيس الهيئة%' OR body LIKE '%ا ً%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[192] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND body LIKE 'بعد الاطلاع على القانون رقم (10) لسن%' AND body LIKE '%ر رئيس الجمهورية رقم (191) لسنة 2009%' AND body LIKE '%سته المنعقدة بتاريخ 2018/4/26.') THEN RAISE EXCEPTION '[192] الديباجة غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE 'تسري أحكام هذا القرار بشأن ضوابط منح%' AND body LIKE '% الأحكام الخاصة بهيكل الملكية أو إجر%' AND body LIKE '%القيد المركزي للأوراق المالية.') THEN RAISE EXCEPTION '[192] المادة 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0 AND body LIKE 'في تطبيق أحكام هذا القرار، يقصد بالك%' AND body LIKE '%ت الاستثمار المباشر.%' AND body LIKE '%زيادة رأس مالها في اكتتاب خاص.' AND body LIKE '%الشركة ذات غرض الاستحواذ (3) (SPECIAL PURPOSE ACQUISITION COMPANY: «SPAC»):%' AND body LIKE '%21- المؤسسات المالية العربية والإقليمية والدولية التي توافق عليها الهيئة.%' AND body LIKE '%المساهم المالك لنسبة 10_ فأكثر%') THEN RAISE EXCEPTION '[192] المادة 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 0 AND body LIKE 'تكون الموافقة على طلبات تأسيس أو ترخ%' AND body LIKE '% للشركات ذات غرض الاستحواذ فتلتزم بت%' AND body LIKE '%شركة مبررات تقبلها الهيئة. (4)') THEN RAISE EXCEPTION '[192] المادة 3 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 4 AND article_suffix_order = 0 AND body LIKE 'مع عدم الإخلال بمتطلبات التأسيس أو ا%' AND body LIKE '%م بدء العمل في النشاط والانتهاء من ا%' AND body LIKE '% موافقة على إجراء هذا التعديل.' AND body LIKE '%نسبة مساهمة المؤسسة المالية عن (25_) من رأس مال الشركة، أو ألا تقل نسبة مساهمة المستثمر المؤهل عن ثلثي رأس مال الشركة%' AND body LIKE '%بالباب الثالث عشر من اللائحة%' AND body LIKE '%ب- ألا تكون الهيئة قد اتخذت ضده%' AND body LIKE '%مالم رد إليه اعتباره.%' AND body LIKE '%ألا يقل نسبة تمثيل المرأة في مجلس إدارة الشركة عن (25_).%') THEN RAISE EXCEPTION '[192] المادة 4 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 5 AND article_suffix_order = 0 AND body LIKE 'مع عدم الإخلال بالمادة (27 مكررًا 1)%' AND body LIKE '%لإخلال بالمادة (27 مكررًا 1) من قانو%' AND body LIKE '%ت بأي شركة من الشركات العاملة.') THEN RAISE EXCEPTION '[192] المادة 5 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 6 AND article_suffix_order = 0 AND body LIKE 'على كل شخص طبيعي أو اعتباري يمتلك 5_%' AND body LIKE '%ى أي شخص طبيعي – بغير طريق الميراث أ%' AND body LIKE '%بالمادة الرابعة من هذا القرار.' AND body LIKE '%يمتلك 5_ من رأس مال%' AND body LIKE '%نسبة 10_ من رأس المال المصدر%' AND body LIKE '%زيادة ملكيته فيها بنسبة 5_ ومضاعفاتها%') THEN RAISE EXCEPTION '[192] المادة 6 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 7 AND article_suffix_order = 0 AND body LIKE 'تقدم طلبات نقل ملكية أسهم الشركات ال%' AND body LIKE '%معتمد من طالب التملك بالأحكام الصادر%' AND body LIKE '%اوز النسب المحددة بهذا القرار.' AND body LIKE '%لنسبة 25_ أو أكثر من رأس المال%' AND body LIKE '%كل من يملك 10_ أو أكثر%') THEN RAISE EXCEPTION '[192] المادة 7 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 8 AND article_suffix_order = 0 AND body LIKE 'يراعى عند البت في طلبات الحصول على م%' AND body LIKE '%س المال أو حقوق التصويت.%' AND body LIKE '% تضعه الهيئة في هذا الشأن. (7)' AND body LIKE '%ثلثي رأس المال أو حقوق التصويت.%' AND body LIKE '%لشركة تمثل 10_ فأكثر من حجم السوق%' AND body LIKE '%أو مجلس إدارة الهيئة بحسب الأحوال قبل إجراء الفحص النافي للجهالة%') THEN RAISE EXCEPTION '[192] المادة 8 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 9 AND article_suffix_order = 0 AND body LIKE 'يعتبر استمرار توافر المتطلبات الخاصة%' AND body LIKE '%نقل ملكية أسهم الشركات العاملة القائ%' AND body LIKE '% بالمادة الرابعة المشار اليها.') THEN RAISE EXCEPTION '[192] المادة 9 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 10 AND article_suffix_order = 0 AND body LIKE 'لا تسري متطلبات التأسيس والترخيص الو%' AND body LIKE '%متطلبات التأسيس والترخيص الواردة بال%' AND body LIKE '%قة المبدئية أو الترخيص المؤقت.') THEN RAISE EXCEPTION '[192] المادة 10 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 11 AND article_suffix_order = 0 AND body LIKE 'على الإدارات المختصة بالهيئة والبورص%' AND body LIKE '%ارات المختصة بالهيئة والبورصة المصري%' AND body LIKE '%تنفيذ هذا القرار كل فيما يخصه.') THEN RAISE EXCEPTION '[192] المادة 11 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 12 AND article_suffix_order = 0 AND body LIKE 'تلغي القرارات التالية: -%' AND body LIKE '%مجلس إدارة الهيئة رقم (65) لسنة 2017%' AND body LIKE '%خر يتعارض مع أحكام هذا القرار.' AND body LIKE '%قرار مجلس إدارة الهيئة رقم (106) لسنة 2015.%' AND body LIKE '%عدا المادة التاسعة منه فتسري على كافة الشركات%') THEN RAISE EXCEPTION '[192] المادة 12 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 13 AND article_suffix_order = 0 AND body LIKE 'ينشر هذا القرار في الوقائع المصرية و%' AND body LIKE '% القرار في الوقائع المصرية وعلى المو%' AND body LIKE '% لتاريخ نشره بالوقائع المصرية.' AND body LIKE '%من اليوم التالي لتاريخ نشره بالوقائع المصرية.%') THEN RAISE EXCEPTION '[192] المادة 13 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 14 AND article_suffix_order = 0 AND body LIKE 'النشاط - نسبة مساهمة المؤسسة المالية%' AND body LIKE '% انخفاض هذه النسبة بعد الترخيص بسبب %' AND body LIKE '%تنظيم نشاط التمويل الاستهلاكي.' AND body LIKE '%Moody’s (Baa)%' AND body LIKE '%A.M Best (B+)%' AND body LIKE '%تصنيفها الائتماني عن المستوى الدال%(BBB+).%' AND body LIKE '%بنسبة لا تقل عن (25_).%') THEN RAISE EXCEPTION '[192] جدول (1) غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 15 AND article_suffix_order = 0 AND body LIKE '(1) تم تعديل القرار بموجب قرار مجلس %' AND body LIKE '%ضافة الفقرة الأخيرة من المادة الثامن%' AND body LIKE '%مل وفقًا للنموذج المتبع لديها.' AND body LIKE '(1) تم تعديل القرار بموجب قرار مجلس إدارة الهيئة رقم 93 بتاريخ 2018/6/10%' AND body LIKE '%وقرار رقم 140 بتاريخ 2024/6/26.%' AND body LIKE '%(5) تم استبدال نص المادة الرابعة%' AND body LIKE '%(9) لا تسري أحكام قرار مجلس إدارة الهيئة رقم 249%' AND body LIKE '%(14) تم تعديل البند رقم 1%رقم (71) لسنة 2009%') THEN RAISE EXCEPTION '[192] الهوامش غير سليم'; END IF;
  IF v_len <> 21671 THEN RAISE EXCEPTION '[192] إجمالى طول المواد % بدل 21671', v_len; END IF;
  RAISE NOTICE '[192] القرار 53/2018: 16 مواد و16 نسخ، إجمالى % حرف', v_len;
END
$verify192$;

COMMIT;
